  '碳移除规模':{'含工程化移除':[500,3000,'万吨/年'],'仅生态碳汇':[0,500,'万吨/年']},
  '建筑能效标准强度':{'超低能耗为主':[80,90,'%'],'现行标准递进':[72,80,'%'],'标准滞后':[60,72,'%']},
  '清洁取暖替代强度':{'全面替代':[95,100,'%'],'分步替代':[80,95,'%'],'局部替代':[60,80,'%']},
