/* ================= 步骤 5 ================= */
let cimResult=null, BAYES=null;   // BAYES: 贝叶斯后验（矩阵+区间），与 cimResult 同生命周期
let profResult=null, profileSel=null;
let corrResult=null, corrPick=null;
let layeredResult=null;
/* 状态级影响值：由描述符级分值按两端状态的高低位置展开 */
// 由描述符级分值按两端状态的高低位置展开——这是"没有人工精判时"的默认假设。
// 它只是兜底，不是真判断：真判断应当落在状态对上，见 impactVal 里的 st 覆盖。
function expandV(v, fn, fi, tn, ti){
  if(!v) return 0;
  const pa=fn>1?(fn-1-fi)/(fn-1):0.5;
  const pb=tn>1?(tn-1-ti)/(tn-1):0.5;
  return v*(2*pa-1)*(2*pb-1);
}
// 状态级影响值：有人工精判就用精判值，否则退回默认展开
function impactVal(fd,fi,td,ti){
  const r=cim[fd+'>'+td];
  if(!r) return 0;
  if(r.st){
    const ov=r.st[fi+'_'+ti];
    if(typeof ov==='number') return ov;
  }
  if(useBayes && BAYES && typeof BAYES.matrix[fd+'>'+td]==='number')
    return BAYES.matrix[fd+'>'+td];
  return expandV(r.v, ST(fd).length, fi, ST(td).length, ti);
}
/* ================= 数值锚定（v1.2 新增：让状态区间参与检算） =================
   原先是一张独立卡片，列出所有描述符再由用户逐个填。现改为长在每个描述符的
   状态面板里——它与状态选择是同一层输入，放在一起才是「选完状态顺手定已知值」。
   卡片形式只剩一句总览（组合空间收窄多少），见 ancSummaryHTML。 */
let anchors={};                       // 描述符名 -> {lo,hi}：已知值或现实区间
function ancOf(nm){ return anchors[nm]||null; }
function ancTxt(nm){
  const a=ancOf(nm); if(!a) return '';
  return a.lo===a.hi ? String(a.lo) : a.lo+'~'+a.hi;
}
function parseAnc(v){
  const t=String(v||'').replace(/\s+/g,'');
  if(!t) return null;
  const p=t.split(/[~～至到]/).filter(x=>x!=='');
  const a=parseFloat(p[0]); if(isNaN(a)) return null;
  const b=p.length>1?parseFloat(p[1]):a;
  if(isNaN(b)) return null;
  return {lo:Math.min(a,b), hi:Math.max(a,b)};
}
function setAnc(nm, v){
  const a=parseAnc(v);
  if(a) anchors[nm]=a; else delete anchors[nm];
  cimResult=null; BAYES=null;                        // 锚定变了，旧结果作废
  corrResult=null;
  profResult=null;
  layeredResult=null;
  render();
}
function clearAnc(){ anchors={}; cimResult=null; BAYES=null; render(); toast('已清除全部数值锚定'); }
corrResult=null;
profResult=null;
layeredResult=null;
/* 锚定后还剩哪些状态可用：区间与锚定完全不相交的排除；
   没有区间的状态不排除（缺少数值依据时，不能凭锚定把它否掉） */
function ancAllowed(nm){
  const st=ST(nm), defs=defsOf(nm), a=ancOf(nm), out=[];
  for(let j=0;j<st.length;j++){
    if(!a){ out.push(j); continue; }
    const d=defs[j];
    if(!d || d.lo===null || d.hi===null || d.lo===undefined || d.hi===undefined){ out.push(j); continue; }
    if(d.hi < a.lo || d.lo > a.hi) continue;
    out.push(j);
  }
  return out;
}
/* 锚定与"已选状态"的冲突：选中状态若与锚定不相交，它不会进枚举，
   但界面上仍显示为已选——必须显式提示，否则用户以为它被检验过了。 */
function ancConflicts(){
  const out=[];
  Object.keys(sel.desc).forEach(nm=>{
    const a=ancOf(nm); if(!a) return;
    const defs=defsOf(nm);
    /* 多选后要逐档核对：勾了三档里有一档与已知值不相交，也得报出来，
       不能只看第一档。 */
    (((sel.desc[nm]||{}).states)||[]).forEach(sn=>{
      const d=defs.filter(x=>x.n===sn)[0];
      if(!d||d.lo===null||d.hi===null||d.lo===undefined||d.hi===undefined) return;
      if(d.hi<a.lo||d.lo>a.hi) out.push({nm:nm, st:sn, lo:d.lo, hi:d.hi, u:d.u||''});
    });
  });
  return out;
}
/* 状态面板里的「已勾范围」一行：B 方案下勾选＝划定可信范围，必须把
   「勾了几档」显式写出来，否则用户仍以为只是打了个标签。 */
function selRangeHTML(nm){
  const k=selIdxOf(nm).length, tot=ST(nm).length;
  if(!k) return '<div class="selrow"><span class="slab">已勾范围</span>'
    +'<span class="sval">不设限（全部 '+tot+' 档都参与检验）</span></div>';
  return '<div class="selrow on"><span class="slab">已勾范围</span>'
    +'<span class="sval"><b>'+k+'</b> / '+tot+' 档</span></div>';
}
/* 状态面板里的「已知值」一行。缩进与 strow 对齐，视觉上属于这个描述符。 */
function ancRowHTML(nm){
  const a=ancOf(nm), defs=defsOf(nm);
  const u=(defs.find(x=>x.u)||{}).u||'';
  const tot=ST(nm).length, al=ancAllowed(nm);
  const dead=!!a&&!al.length;
  return `<div class="ancrow${a?' on':''}${dead?' dead':''}">`
    +`<span class="alab">已知值</span>`
    +`<input class="txt ancin${a?' on':''}" value="${ancTxt(nm)}" placeholder="不限，如 4.8 或 4.5~5.0"`
    +` onchange="setAnc('${nm}',this.value)">`
    +`<span class="aunit">${u||'—'}</span>`
    +`<span class="acnt">${a?(dead?('<b>0</b> / '+tot):('<b>'+al.length+'</b> / '+tot)):('全部 '+tot)}</span>`
    +(a?`<span class="ancx" onclick="setAnc('${nm}','')">清除</span>`:'')
    +`</div>`
    +(dead?`<div class="stbad">锚定把这个描述符的所有状态都排除了——检验会直接报错，请放宽已知值或改区间。</div>`:'');
}
/* 锚定总览：放在状态面板底部，只讲「收窄了多少」，不再重复列出所有输入框。 */
function ancSummaryHTML(){
  const ds=Object.keys(sel.desc);
  if(!ds.length) return '';
  let before=1, after=1, nA=0;
  ds.forEach(nm=>{ before*=ST(nm).length; after*=ancAllowed(nm).length; if(ancOf(nm)) nA++; });
  if(!nA) return '';
  const deadOnes=ds.filter(nm=>ancOf(nm)&&!ancAllowed(nm).length);
  let h=`<div class="ancsum">已给 <b>${nA}</b> 个描述符设定已知值：组合空间由 <b>${before.toLocaleString()}</b> 收窄为 <b>${after.toLocaleString()}</b> 种`;
  if(before>after) h+=`（排除 ${(before-after).toLocaleString()} 种）`;
  h+=`。<b>改变已知值后需重新运行检验。</b>　<a class="ancx" onclick="clearAnc()">全部清除</a>`;
  h+=`<br>只有与已知值<b>完全不相交</b>的状态才被排除；部分重叠的保留，因为它仍可能与已知值相容。</div>`;
  if(deadOnes.length){
    h+=`<div class="note" style="margin-top:10px;">有描述符在已知值下<b>一个可用状态都不剩</b>——`
      +`这套设定在数值上无解。要么放宽已知值，要么调整那些状态的取值区间。</div>`;
  }
  return h;
}
/* 选中的状态与已知值不相交时必须显式提示：否则用户以为它被检验过了。
   它在枚举里确实不会出现（ancAllowed 把它排除了），界面上却仍显示为已选。 */
function ancConflictHTML(){
  const cf=ancConflicts();
  if(!cf.length) return '';
  return '<div class="pwarn"><b>你选中的档与已知值不相容：</b>'
    +cf.map(x=>x.nm+'「'+x.st+' '+x.lo+'–'+x.hi+(x.u?' '+x.u:'')+'」vs 已知值 '+ancTxt(x.nm)).join('；')
    +'。检验时这些状态不会被考虑——请改选状态、放宽已知值，或确认已知值本身有误。</div>';
}

/* 档位对索引表：给每一对描述符分配一段连续空间，把「档位 (a,b) 共存过没有」记成 0/1。
   规模 = Σ_{i<j} sizes[i]×sizes[j]，19 个描述符平均 3 档时约 1.5KB。
   为什么要在枚举里逐条打点、而不是事后从 consistent 反推：那个数组有 200 组上限，
   抽样时还会截断，反推出来的"从未共存"会把"没抽到"误判成"不可能"。 */
function pairIndexTable(n,sizes){
  const off=new Int32Array(n*n).fill(-1), wid=new Int32Array(n*n);
  let total=0;
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){
    off[i*n+j]=total; wid[i*n+j]=sizes[i]*sizes[j]; total+=wid[i*n+j];
  }
  return {n:n, off:off, wid:wid, total:total};
}
/* 枚举核心：一致性检验与影响谱共用。
   force = {pos, idx} 时把第 pos 个描述符钉死在某个状态上，用于「如果我强行这样，情景集会怎么变」。 */
function enumCore(ds, force, capN, keepAll){
  const n=ds.length;
  const sizes=ds.map(d=>ST(d).length);
  if(sizes.some(x=>x<1)) return {bad:'状态缺失'};
  /* 数值锚定在枚举之前生效：与锚定值完全不相交的状态直接排除 */
  const allowed=ds.map(d=>ancAllowed(d));
  /* 勾选＝划定可信范围：勾了的档位才是候选，枚举只在范围内找自洽情景。
     一个都没勾的描述符不设限（"全部档位都可能"），所以空选不会把空间清零。 */
  ds.forEach((d,i)=>{
    const picked=((sel.desc&&sel.desc[d]||{}).states)||[];
    if(picked.length) allowed[i]=allowed[i].filter(j=>picked.indexOf(ST(d)[j])>=0);
  });
  if(force) allowed[force.pos]=[force.idx];
  const dead=allowed.findIndex(a=>!a.length);
  if(dead>=0){
    /* 分清是锚定排空的还是勾选排空的——两种情况的补救办法不一样 */
    return {dead:dead, deadBy:(ancAllowed(ds[dead]).length?'sel':'anc')};
  }
  const radix=allowed.map(a=>a.length);
  const space=radix.reduce((a,b)=>a*b,1);
  const MAX=capN||200000;
  const sampled=space>MAX;
  const N=Math.min(space,MAX);
  /* 预计算影响值，避免内层重复解析 */
  const IMP=[];
  for(let k=0;k<n;k++){
    IMP[k]=[];
    for(let i=0;i<n;i++){
      if(k===i){ IMP[k][i]=null; continue; }
      const m=[];
      for(let a=0;a<sizes[k];a++){
        const row=[];
        for(let b=0;b<sizes[i];b++) row.push(impactVal(ds[k],a,ds[i],b));
        m.push(row);
      }
      IMP[k][i]=m;
    }
  }
  const idxOf=new Array(n).fill(0);
  const consistent=[], seen=new Set(), presence=new Set(), freq={};
  /* 「全局互斥对」要的数据：每一对描述符的每一组档位对，有没有在任何自洽情景里共存过。
     按对分片记一个字节，总容量是各对档位数之积的和（19 个描述符约两千字节）。
     必须在这里逐条累积，不能事后从 consistent 数组反推——那个数组有 200 组上限，会截断。 */
  const ptab=pairIndexTable(n,sizes), pseen=new Uint8Array(ptab.total);
  let inconsistent=0, count=0;
  for(let c=0;c<N;c++){
    let x = sampled ? Math.floor(Math.random()*space) : c;
    for(let i=n-1;i>=0;i--){ const r=radix[i]; idxOf[i]=allowed[i][x%r]; x=Math.floor(x/r); }
    let ok=true;
    for(let i=0;i<n && ok;i++){
      let mx=-1e9, pickv=0;
      for(let j=0;j<sizes[i];j++){
        let acc=0;
        for(let k=0;k<n;k++){ if(k!==i) acc+=IMP[k][i][idxOf[k]][j]; }
        if(j===idxOf[i]) pickv=acc;
        if(acc>mx) mx=acc;
      }
      if(pickv<mx-1e-6) ok=false;
    }
    if(ok){
      const key=idxOf.join(',');
      if(!seen.has(key)){
        seen.add(key); count++;
        if(keepAll){ if(consistent.length<keepAll) consistent.push(idxOf.slice()); }
        else if(consistent.length<200) consistent.push(idxOf.slice());
        for(let i=0;i<n;i++){
          const kk=i+'|'+idxOf[i];
          presence.add(kk);
          freq[kk]=(freq[kk]||0)+1;
          for(let j=i+1;j<n;j++)
            pseen[ptab.off[i*n+j]+idxOf[i]*ptab.wid[i*n+j]+idxOf[j]]=1;
        }
      }
    } else inconsistent++;
  }
  return {n:n, sizes:sizes, space:space, checked:N, sampled:sampled,
    consistent:consistent, count:count, inconsistent:inconsistent,
    presence:presence, freq:freq, dead:-1,
    ptab:ptab, pseen:pseen,
    truncated: keepAll ? (count>keepAll) : false};
}

function runCIM(){
  if(useBayes && !BAYES) computeBayes();
  const ds=Object.keys(sel.desc);
  const pe=prepErr(ds);
  if(pe){ toast(pe); return; }
  const r=enumCore(ds,null);
  if(r.bad){ toast('有描述符缺少状态定义'); return; }
  if(r.dead>=0){ toast('「'+ds[r.dead]+'」在锚定下没有任何可用状态，请放宽锚定或改区间'); return; }
  const total=ds.reduce((a,d)=>a*ST(d).length,1);
  const anchored=ds.filter(d=>ancOf(d)).length;
  cimResult={ds:ds.slice(), sizes:r.sizes.slice(), total:total, space:r.space, anchored:anchored,
    checked:r.checked, sampled:r.sampled,
    consistent:r.consistent, inconsistent:r.inconsistent, ts:nowStr()};
  toast('检验完成：'+(r.sampled?'抽样 ':'')+r.checked.toLocaleString()+' 个组合，自洽 '+r.consistent.length+' 组'
    +(anchored?('（锚定已把空间收窄到 '+r.space.toLocaleString()+' 种）'):''));
  render();
}
/* ================= 逐层求解（v1.2 新增：让跨层约束真正进入求解） =================
   与「跨层一致性」的区别：那个是算完之后再查档位差；这个是在求解时就用上级的取值
   裁掉下级不相容的状态——上级定了「目标节奏（21–28%）」，下级「快速清洁化（30–40%）」
   根本不会进入枚举，而不是等算出来再判它矛盾。 */
function rangeOf(nm,scope){
  const base=baseOf(nm);
  if(scope==='region') return base;
  const ov=(stateDefsScope[nm]||{})[scope]||{};
  return base.map(x=>{ const o=ov[x.n]; return o?{...x,...o}:{...x}; });
}
// 上级某状态 -> 它那一层的区间；下级哪个状态与它相交，才算相容
function allowUnder(ds,scope,parent){
  return ds.map(d=>{
    const sizes=ST(d).length;
    if(!parent) return [...Array(sizes).keys()];
    const pi=parent.cb[ds.indexOf(d)];
    const pName=ST(d)[pi];
    const pR=rangeOf(d,parent.scope).find(x=>x.n===pName);
    const cDefs=rangeOf(d,scope);
    const ok=[];
    for(let j=0;j<sizes;j++){
      const c=cDefs[j];
      if(!pR||pR.lo===null||pR.hi===null||c.lo===null||c.hi===null){ ok.push(j); continue; }
      if(c.hi < pR.lo || c.lo > pR.hi) continue;     // 与上级区间不相交，直接排除
      ok.push(j);
    }
    return ok;
  });
}
/* 求解内核（v1.3 重写，支撑 19 描述符规模）：
   一条组合是否自洽只取决于它自己（各描述符取值 + 影响矩阵），与上级约束无关——
   上级约束只负责「筛」，不参与「判」。所以整层只判一遍（上限 25 万次，大空间按
   固定种子抽样），再按各组做归桶筛选；旧版是每组各枚举一遍（600 组 × 每组 20 万
   次），19 个描述符时根本跑不完。归桶：按前三维取值建索引，每组只在自己允许的
   桶里逐条核对其余维，避免全量×全组的两两比对。 */
const LAYER_BUDGET=250000, LAYER_KEEP=80000;

function solveLayer(ds, scope, parents, cap){
  cap=cap||600;
  const sizes=ds.map(d=>ST(d).length);
  const IMP=buildIMP(ds,cim);
  const groups=(parents&&parents.length)?parents:[{path:[],scope:null,cb:null}];
  const space=sizes.reduce((a,b)=>a*b,1);
  const N=Math.min(space,LAYER_BUDGET);
  const sampled=space>N;
  const rnd=sampled?mulberry(20261017):null;
  const rr=mulberry(7);              // 蓄水池抽样用：超出保留上限时等概率替换，避免字典序偏置
  const consist=[]; let kept=0;
  let checked=0, incon=0;
  for(let c=0;c<N;c++){
    let x=sampled?Math.floor(rnd()*space):c;
    const cb=new Array(ds.length);
    for(let i=ds.length-1;i>=0;i--){ cb[i]=x%sizes[i]; x=Math.floor(x/sizes[i]); }
    checked++;
    if(evalCombo(IMP,sizes,cb)){
      kept++;
      if(consist.length<LAYER_KEEP) consist.push(cb);
      else{ const j=Math.floor(rr()*kept); if(j<LAYER_KEEP) consist[j]=cb; }
    }
    else incon++;
  }
  const depth=Math.min(3,ds.length);
  const buckets=new Map();
  consist.forEach(cb=>{
    let k=0;
    for(let i=0;i<depth;i++) k=k*sizes[i]+cb[i];
    let b=buckets.get(k); if(!b){ b=[]; buckets.set(k,b); }
    b.push(cb);
  });
  const out=[]; let dead=0, trunc=false;
  groups.forEach(par=>{
    /* 上级的 scope/cb 挂在本组 path 的最后一节——v1.3 之前这里读的是顶层字段，
       链式层级时恒为 undefined，上级约束从未真正传进 allowUnder（旧测试全零矩阵
       恰好掩盖了它）。现在统一从 path 末节取。 */
    const tail=(par.path&&par.path.length)?par.path[par.path.length-1]:null;
    const pscope=par.scope||(tail?tail.scope:null);
    const pcb=par.cb||(tail?tail.cb:null);
    const allowed=allowUnder(ds,scope,(pscope&&pcb)?{scope:pscope,cb:pcb}:null);
    if(allowed.some(a=>!a.length)){ dead++; return; }
    const am=allowed.map(a=>a.reduce((m,j)=>m|(1<<j),0));
    if(am.some(m=>!m)){ dead++; return; }
    const cands=[];
    const rec=(i,k)=>{
      if(i===depth){ const b=buckets.get(k); if(b) for(let t=0;t<b.length;t++) cands.push(b[t]); return; }
      let m=am[i];
      for(let j=0;m;j++,m>>=1){ if(m&1) rec(i+1,k*sizes[i]+j); }
    };
    rec(0,0);
    for(let t=0;t<cands.length;t++){
      const cb=cands[t];
      let ok=true;
      for(let i=depth;i<ds.length;i++){
        if(!((am[i]>>cb[i])&1)){ ok=false; break; }
      }
      if(!ok) continue;
      if(out.length<cap) out.push({path:par.path.concat([{scope:scope, cb:cb.slice()}])});
      else trunc=true;
    }
  });
  return {sols:out, checked:checked, incon:incon, dead:dead, groups:groups.length,
    truncated:trunc, sampled:sampled, space:space, consistN:kept};
}
function runLayered(){
  const order=xlayers().filter(s=>s!=='nation');     // 国家级是给定层，不参与枚举
  if(!order.length){ toast('第 1 步至少要勾一个参与求解的层级（区域 / 省 / 市）'); return; }
  const ds=Object.keys(sel.desc);
  const pe=prepErr(ds);
  if(pe){ toast(pe); return; }
  const layers=[]; let parents=null;
  layeredResult=null;
  const step=()=>{
    const scope=order[layers.length];
    setTimeout(()=>{
      const r=solveLayer(ds, scope, parents);
      layers.push({scope:scope, n:r.sols.length, checked:r.checked,
                   incon:r.incon, dead:r.dead, groups:r.groups, truncated:r.truncated,
                   sampled:r.sampled, space:r.space});
      parents=r.sols;
      if(!parents.length||layers.length===order.length){
        layeredResult={ds:ds.slice(), order:order.slice(), layers:layers,
          combos:parents?parents.length:0, final:parents||[], ts:nowStr()};
        render();
        toast('逐层求解完成：'+layers.map(x=>XL_NAME[x.scope]+' '+x.n+' 组'+(x.truncated?'+':'')).join(' → ')
          +(layers.some(x=>x.dead)?('（'+layers.reduce((a,x)=>a+x.dead,0)+' 个上级情景下级无解）'):'')
          +(layers.some(x=>x.sampled)?'　·　大空间层为抽样估计':''));
      }
      else step();
    }, 30);
  };
  step();
}

/* 逐层求解的出口。原先是第 7 步一张常驻卡片，占着一屏却只在勾了多层辖区时才有内容；
   决策三把它下沉成检验结果卡里的一个默认收起的折叠段。
   这里只讲逐层求解本身：上级取值约束下级、逐层往下推的结果。
   跨层约束到这一步只剩一条数值判据——上级某档与下级某档区间完全不相交时不进枚举
   （allowUnder）。界面那套「方向相差 ≥2 档」的筛档 v1.5.7 已撤：它只改界面可选性、
   不进检算与导出，留着反而让人以为选过的档位参与了结果。 */
function renderLay(){
  const host=document.getElementById('layBox'); if(!host) return;
  const ds=Object.keys(sel.desc);
  const order=xlayers().filter(s=>s!=='nation');
  // 没勾多层时这一段没有意义，直接收起整段（连 summary 一起藏），不占读者注意力
  const fold=document.getElementById('layFold');
  const applicable=ds.length>=2&&order.length>=2;
  if(fold) fold.style.display=applicable?'':'none';
  if(!applicable){
    host.innerHTML='';
    if(fold&&/layFold/.test(fold.innerHTML)===false) fold.open=false;
    return;
  }
  if(!layeredResult){
    host.innerHTML='<div style="font-size:13px;line-height:1.85;">'
      +'<b>还没有逐层求解结果。</b>点下面的按钮，平台先解「'+XL_NAME[order[0]]+'」，'
      +'再把每个自洽情景的取值转成下一层的约束，逐层往下推。<br>'
      +'<span class="dim">求解顺序：'+order.map(s=>XL_NAME[s]).join(' → ')+'　·　描述符 '+ds.length+' 个</span>'
      +'<div style="margin-top:12px;"><button class="btn pri" onclick="runLayered()">运行逐层求解</button></div>'
      +'<div class="dim" style="font-size:13px;margin-top:9px;">'
      +'国家级是给定层（取值来自政策目标），不参与枚举；若第 1 步没有勾选区域/省/市中的任何一个，这里无法求解。</div></div>';
    return;
  }
  const R=layeredResult;
  let h='<div class="layflow">';
  R.layers.forEach((L,i)=>{
    h+='<div class="laynode"><div class="ln">'+XL_NAME[L.scope]+'</div>'
      +'<div class="lv">'+L.n.toLocaleString()+(L.truncated?'<i>+</i>':'')+' 组</div>'
      +'<div class="ls">检查 '+L.checked.toLocaleString()+(L.sampled?'（抽样）':'')
      +(L.dead?('　<span class="laywarn">'+L.dead+' 个上级无解</span>'):'')+'</div></div>';
    if(i<R.layers.length-1) h+='<div class="layarrow">→</div>';
  });
  h+='</div>';
  if(R.layers.some(x=>x.sampled)){
    h+='<div class="dim" style="font-size:13px;margin:6px 0 0;">'
      +'标注「抽样」的层组合空间超过 25 万，按固定种子抽样估计（自洽组合数是<b>下限</b>，'
      +'小空间层仍为精确枚举）。</div>';
  }
  h+=kv('最终跨层相容组合', '<span style="color:var(--pri);font-weight:600;">'+R.combos.toLocaleString()
    +(R.layers.some(x=>x.truncated)?'+':'')+' 条</span>', 'margin-top:4px');
  if(R.layers.some(x=>x.truncated)){
    h+='<div class="dim" style="font-size:13px;margin:6px 0 10px;">'
      +'带 + 号的层已达展示上限（600 组），实际数量可能更多。缩小描述符范围可得到完整结果。</div>';
  }
  if(R.combos){
    h+='<div style="margin-top:12px;font-size:13px;color:var(--tx3);">以下为跨层相容的组合，每条都记录了它在各层的取值：</div>';
    h+='<div style="margin-top:8px;">';
    R.final.slice(0,6).forEach((f,i)=>{
      const segs=f.path.map(p=>{
        const t=p.cb.map((v,j)=>(DSHORT[R.ds[j]]||R.ds[j])+'＝'+ST(R.ds[j])[v]).join('、');
        return '<b>'+XL_NAME[p.scope]+'</b>　'+t;
      }).join('<span class="laysep">→</span>');
      h+='<div class="layrow"><span class="layidx">#'+(i+1)+'</span><span>'+segs+'</span></div>';
    });
    h+='</div>';
    if(R.combos>6) h+='<div class="dim" style="font-size:13px;margin-top:7px;">此处显示前 6 条，共 '+R.combos+' 条（上限 600）。</div>';
  }else{
    h+='<div class="note" style="margin-top:10px;">没有找到跨层相容的组合。'
      +'常见原因是上级某层的区间设得比下级宽松太多，导致下级无解——可以切到第 3 步，'
      +'把相应层级的区间调一调，或者换几个描述符再试。</div>';
  }
  h+='<div style="margin-top:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'
    +'<button class="btn sm" onclick="runLayered()">重新求解</button>'
    +'<span class="dim" style="font-size:13px;">计算时间 '+R.ts+'</span></div>';
  host.innerHTML=h;
}

/* 「我选的那套情景」到底成不成立——这是状态选择的用处。
   枚举不预设取值，但用户确实需要知道自己的主张站不站得住：
   若不自洽，指出哪几个描述符的选定状态不是自己的最高分，并给出应改成哪一档。 */
function selectedCombo(ds){
  return ds.map(d=>{
    const sn=((sel.desc[d]||{}).states||[])[0];
    return sn?ST(d).indexOf(sn):-1;
  });
}
/* 「你选的情景」站不站得住。
   多选语义下，只有当每个描述符都恰好勾了一档，才存在"唯一的一套情景"；
   若有人勾了多档，那划的是范围——这时判"某一条情景自不自洽"没有意义，
   改为报"范围里有多少种组合最终是自洽的"，这才是 B 方案该给的回答。 */
function checkSelected(ds){
  const cb=selectedCombo(ds);
  const missing=cb.filter(x=>x<0).length;
  if(missing) return {missing:missing};
  const multi=ds.filter(d=>selIdxOf(d).length>1);
  if(multi.length) return {range:true, multi:multi, cb:cb};
  const IMP=buildIMP(ds,cim), sizes=ds.map(d=>ST(d).length), rows=[];
  let ok=true;
  ds.forEach((d,i)=>{
    let pick=0, mx=-1e9, mi=0;
    for(let j=0;j<sizes[i];j++){
      let acc=0;
      for(let k=0;k<ds.length;k++){ if(k!==i) acc+=IMP[k][i][cb[k]][j]; }
      if(j===cb[i]) pick=acc;
      if(acc>mx){ mx=acc; mi=j; }
    }
    if(pick<mx-1e-6) ok=false;
    rows.push({d:d, at:cb[i], pick:pick, max:mx, best:mi, gap:mx-pick});
  });
  return {ok:ok, rows:rows, cb:cb};
}
/* 范围模式下：勾选范围内一共有多少种组合、其中多少种是自洽的。
   这是 B 方案的直接回报——"我划的这块范围里，有多少真的成立"。 */
function rangeStat(){
  if(!cimResult) return null;
  const ds=cimResult.ds;
  const inRange=cimResult.consistent.filter(cb=>
    ds.every((d,i)=>{ const s=selIdxOf(d); return !s.length||s.indexOf(cb[i])>=0; }));
  return {n:rangeSize(ds), ok:inRange.length, total:cimResult.consistent.length,
    anySel:ds.some(d=>selIdxOf(d).length)};
}
let allScen=false;   // 是否展开全部自洽情景（默认只列前 6 个，避免几百组把页面拖慢）
function toggleAllScen(){ allScen=!allScen; render(); }
function checkResult(){
  const ds=Object.keys(sel.desc);
  if(ds.length<2){ el('checkResult','<div class="empty">先在第 3 步勾选至少两个描述符</div>'); return; }
  if(!cimResult){
    el('checkResult','<div style="font-size:13px;line-height:1.8;">'
      +'<b>还没有检验结果。</b>点下面的按钮，平台会枚举全部状态组合，逐个算出每个描述符的影响平衡值，'
      +'把「所有描述符的选定状态都是各自平衡里得分最高的那一个」的组合挑出来——这些就是自洽情景。'
      +'<div style="margin-top:12px;"><button class="btn pri" onclick="runCIM()">运行一致性检验</button></div>'
      +'<div class="dim" style="font-size:13px;margin-top:9px;">组合数＝各描述符状态数之积。'
      +'19 个描述符全选时约 3¹⁷×2² ≈ 5.17 亿种，远超可枚举范围，此时平台会自动改为随机抽样检验并标注。</div></div>');
    return;
  }
  const r=cimResult;
  let h=kv('参与检验的描述符', r.ds.length+' 个')
   +kv('状态总数', r.sizes.reduce((a,b)=>a+b,0)+' 个')
   +kv('组合空间', r.total.toLocaleString()+' 种'
   +(r.anchored?(' <span style="color:var(--pri);">→ 锚定后 '+(r.space||r.total).toLocaleString()+' 种</span>'):''))
   +(r.anchored?kv('数值锚定排除','<span style="color:var(--pri);">'
     +(r.total-(r.space||r.total)).toLocaleString()+' 种组合（'+r.anchored+' 个描述符已锚定）</span>'):'')
   +kv('实际检查', (r.sampled?('随机抽样 '+r.checked.toLocaleString()+' 种'):(r.checked.toLocaleString()+' 种（全枚举）')))
   +kv('自洽情景', '<span style="color:var(--ok);font-weight:600;">'
     +r.consistent.length+(r.consistent.length>=200?'+':'')+' 组</span>')
   +kv('不自洽组合', '<span style="color:var(--rd);">'+r.inconsistent.toLocaleString()+' 组</span>')
   +'<div style="margin-top:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'
   +'<button class="btn sm" onclick="runCIM()">重新检验</button>'
   +'<span class="dim" style="font-size:13px;">计算时间 '+r.ts+'</span></div>';

  const sc=checkSelected(r.ds);
  if(sc.missing){
    h+='<div class="note" style="margin-top:12px;">还有 <b>'+sc.missing+'</b> 个描述符没勾状态。'
      +'不勾＝不设限（该描述符的全部档位都参与检验），所以检验照跑；'
      +'但要说清「你主张的那套情景自不自洽」，得先到第 3 步把它勾出来。</div>';
  }else if(sc.range){
    /* 多选＝划定范围：这时不存在"唯一那套情景"，改答"你划的这块范围里有多少真的成立" */
    const rs=rangeStat();
    h+='<div class="rrange" style="margin-top:12px;">'
      +'<b>你划定的范围：'+rs.n.toLocaleString()+' 种组合</b>'
      +'（勾了多档的描述符：'+sc.multi.map(d=>DSHORT[d]||d).join('、')+'）。<br>'
      +'其中 <b style="color:var(--ok);">'+rs.ok+' 组</b>是自洽的'
      +'（占本次检出的 '+rs.total+' 组自洽情景的 '
      +Math.round(rs.ok/Math.max(1,rs.total)*100)+'%）。'
      +(rs.ok?'':'<br><span style="color:var(--rd);">你划的这块范围里没有任何自洽情景——'
        +'说明这些档位的组合与当前打分矩阵不相容，需要放宽范围或复核相关判断。</span>')
      +'</div>';
  }else if(sc.ok){
    const idx=r.consistent.findIndex(cb=>cb.join(',')===sc.cb.join(','));
    h+='<div class="rok" style="margin-top:12px;"><b>你选的情景：自洽。</b>'
      +(idx>=0?('就是下面第 '+(idx+1)+' 个自洽情景；导出目标模型时用的就是这一组。')
        :'在本次抽样中未直接出现，但按当前打分它满足一致性判据。')+'</div>';
  }else{
    const bad=sc.rows.filter(x=>x.gap>1e-6).sort((a,b)=>b.gap-a.gap);
    h+='<div class="rnote" style="margin-top:12px;"><b>你选的情景：不自洽。</b>'
      +'有 '+bad.length+' 个描述符的选定状态不是自身的最高分：<br>'
      +bad.map(x=>'· '+x.d+'：取「'+ST(x.d)[x.at]+'」平衡 '+x.pick.toFixed(1)
        +'，而「'+ST(x.d)[x.best]+'」为 '+x.max.toFixed(1)+'（差 '+x.gap.toFixed(1)+'）').join('<br>')
      +'<br>要让它成立，至少把这些描述符改成括号里的高分档；或者回打分页复核相关判断。</div>';
  }
  if(!r.consistent.length){
    h+='<div class="note" style="margin-top:12px;">没有找到自洽情景。这通常说明打分矩阵内部冲突较多，'
      +'或者描述符选得太多。可以回「交叉影响打分」复核那些低置信度的判断，再跑一次。</div>';
  }else{
    const showN=allScen?r.consistent.length:Math.min(6,r.consistent.length);
    h+='<div style="margin-top:10px;">';
    r.consistent.slice(0,showN).forEach((cb,i)=>{ h+=scenCard(r,i,cb); });
    h+='</div>';
    if(r.consistent.length>6){
      h+='<div style="margin-top:9px;display:flex;gap:10px;flex-wrap:wrap;align-items:center;">'
        +'<button class="btn sm" onclick="toggleAllScen()">'
        +(allScen?('收起，只显示前 6 组'):('展开全部 '+r.consistent.length+' 组'))
        +'</button>'
        +'<button class="btn sm" onclick="downloadAll()">下载完整清单（csv）</button>'
        +'<span class="dim" style="font-size:13px;">组数多时展开会略慢，可先下载清单再挑。</span></div>';
    }else{
      h+='<div class="dim" style="font-size:13px;margin-top:8px;">'
        +'<button class="btn sm" onclick="downloadAll()">下载完整清单（csv）</button></div>';
    }
  }
  el('checkResult',h);
}
function scenCard(r,i,cb){
  const open=openScen===i;
  let t='';
  r.ds.forEach((d,j)=>{ if(j) t+=' · '; t+=(DSHORT[d]||d)+'='+(ST(d)[cb[j]]||'?'); });
  return '<div class="acc"><div class="ah" onclick="toggleScen('+i+')">'
    +'<span class="t">情景 '+(i+1)+'　<span class="dim">'+t+'</span></span>'
    +'<span style="font-size:13px;color:var(--pri);">'+(open?'收起 ▲':'展开判断链 ▼')+'</span></div>'
    +(open?('<div class="ab">'+scenDetail(r,cb)+'</div>'):'')+'</div>';
}
function scenDetail(r,cb){
  let h='<div style="margin-bottom:8px;font-size:13px;">各描述符的取值，'
    +'以及它在本情景下各状态的影响平衡值（加粗者为选定状态，▲ 为该描述符的最高分）：</div>';
  r.ds.forEach((d,i)=>{
    const sts=ST(d), defs=defsOf(d);
    const bal=[];
    for(let j=0;j<sts.length;j++){
      let s=0;
      for(let k=0;k<r.ds.length;k++){ if(k!==i) s+=impactVal(r.ds[k],cb[k],d,j); }
      bal.push(s);
    }
    let mx=-1e9, mi=0;
    bal.forEach((v,j)=>{ if(v>mx){ mx=v; mi=j; } });
    const sx=defs[cb[i]];
    h+='<div style="margin:9px 0;padding:9px 10px;border:1px solid var(--pri-b);border-radius:6px;">'
      +'<div style="font-size:13px;"><b>'+d+'</b>　取「'+sts[cb[i]]+'」'
      +(sx?'　'+rngTxt(sx):'')+'</div>'
      +'<div style="font-size:13px;color:var(--tx2);margin-top:3px;line-height:1.9;">'
      +sts.map((s,j)=>s+' <b'+(j===cb[i]?' style="color:var(--ok)"':'')+'>'
        +(bal[j]>0?'+':'')+bal[j].toFixed(1)+'</b>'+(j===mi?' ▲':'')).join('　｜　')
      +'</div></div>';
  });
  h+='<div style="margin-top:10px;padding-top:9px;border-top:1px dashed var(--line);font-size:13px;line-height:1.8;">'
   +'<b>为什么自洽：</b>每个描述符的选定状态，都是它自身影响平衡值中得分最高的那一项——'
   +'没有任何其他状态受到更强的合力支持。这就是 CIB 的一致性原则。</div>';
  return h;
}
function toggleScen(i){ openScen=openScen===i?null:i; render(); }
/* 共存查询：给一对档位，问「它们一起出现过吗」。
   优先用枚举时打的 pseen 点阵——精确，且不受 consistent 数组 200 组上限的截断影响；
   只在拿到旧版结果对象（没有点阵）时才退回 consistent 数组。 */
function coFn(r){
  const n=r.ds.length, sz=r.sizes;
  if(r.ptab&&r.pseen){
    const t=r.ptab;
    return {has:function(i,a,j,b){ return !!r.pseen[t.off[i*n+j]+a*sz[j]+b]; }};
  }
  const cons=r.consistent;
  return {has:function(i,a,j,b){ return cons.some(c=>c[i]===a&&c[j]===b); }};
}
/* 每个档位在自洽集里出现过没有。没出现过的叫「孤立档位」——
   它跟「互斥对」是两回事：孤立档位是这档自己站不住，互斥对是两档各自都行、凑一起不行。 */
function aliveTable(r){
  const n=r.ds.length, sz=r.sizes, out=[];
  if(r.presence){
    for(let i=0;i<n;i++){
      const a=[]; for(let j=0;j<sz[i];j++) a.push(r.presence.has(i+'|'+j));
      out.push(a);
    }
    return out;
  }
  const cf=coFn(r);
  for(let i=0;i<n;i++){
    const a=[];
    for(let j=0;j<sz[i];j++){
      let any=false;
      for(let k=0;k<n&&!any;k++){
        if(k===i) continue;
        for(let b=0;b<sz[k];b++){
          const lo=Math.min(i,k), hi=Math.max(i,k);
          const aa=(i<k)?j:b, bb=(i<k)?b:j;
          if(cf.has(lo,aa,hi,bb)){ any=true; break; }
        }
      }
      a.push(any);
    }
    out.push(a);
  }
  return out;
}
/* 档位出现次数（用来自排优先级）：出现得越多、却从没凑到一起的，越值得看。 */
function freqOf(r,i,a){
  if(r.freq&&r.freq[i+'|'+a]!=null) return r.freq[i+'|'+a];
  const cf=coFn(r); let c=0;
  for(let k=0;k<r.ds.length;k++){
    if(k===i) continue;
    for(let b=0;b<r.sizes[k];b++){
      const lo=Math.min(i,k), hi=Math.max(i,k);
      const aa=(i<k)?a:b, bb=(i<k)?b:a;
      if(cf.has(lo,aa,hi,bb)) c++;
    }
  }
  return c;
}
/* 全局互斥对：不看用户选了什么，把这次检验里所有描述符对的档位组合过一遍，列出
   「两个档位各自都出现过，却从未一起出现过」的组合——这就是「所有枚举场景的矛盾」
   的可读形式。枚举出的自洽情景本身没有矛盾，矛盾在被筛掉的那几亿个组合里，
   逐条开建议不现实；以"档位对"为单位就只有 Σ sizes[i]×sizes[j] 项（约 1500 项），一次算完。 */
function exclPairs(){
  if(!cimResult) return {need:'check'};
  const r=cimResult;
  if(!r.consistent) return {need:'check'};
  if(!r.consistent.length) return {need:'empty'};
  const ds=r.ds, sz=r.sizes, n=ds.length;
  if(n<2) return {need:'few'};
  const cf=coFn(r), alive=aliveTable(r);
  const solo=[];
  ds.forEach((d,i)=>{ for(let a=0;a<sz[i];a++) if(!alive[i][a]) solo.push({i:i,a:a}); });
  const maxF=Math.max(1,r.consistent.length), out=[];
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){
    for(let a=0;a<sz[i];a++){
      if(!alive[i][a]) continue;                 // 孤立档位不在"互斥对"里重复计入
      for(let b=0;b<sz[j];b++){
        if(!alive[j][b]) continue;
        if(cf.has(i,a,j,b)) continue;           // 共存过，不是矛盾
        const altA=[], altB=[];
        for(let k=0;k<sz[i];k++) if(k!==a&&alive[i][k]&&cf.has(i,k,j,b)) altA.push(k);
        for(let k=0;k<sz[j];k++) if(k!==b&&alive[j][k]&&cf.has(i,a,j,k)) altB.push(k);
        out.push({i:i, j:j, ai:a, bj:b, altA:altA, altB:altB,
          w:Math.min(freqOf(r,i,a),freqOf(r,j,b))/maxF});
      }
    }
  }
  out.sort((x,y)=>y.w-x.w);
  return {pairs:out, solo:solo, ds:ds, n:n, sampled:r.sampled, nCons:r.consistent.length};
}
/* ================= 矛盾组合与处理建议（v1.3：改为真算，不再用写死的表） =================
   判据：在本次检验的自洽情景集里，你所选情景中的某两个状态从未同时出现过，
   就说明这两个要求在现有判断体系下不能并存。
   建议也是算出来的：从自洽集里找与其中一边共存过的另一档，点一下会真的改状态并重跑。 */
function confPairs(){
  if(!cimResult) return {need:'check'};
  const ds=cimResult.ds, cons=cimResult.consistent;
  if(!cons.length) return {need:'empty'};
  const cb=selectedCombo(ds);
  if(cb.some(x=>x<0)) return {need:'missing'};
  const out=[];
  for(let i=0;i<ds.length;i++) for(let j=i+1;j<ds.length;j++){
    const ai=cb[i], bj=cb[j];
    if(cons.some(c=>c[i]===ai&&c[j]===bj)) continue;
    const altA=[], altB=[];
    for(let k=0;k<ST(ds[i]).length;k++){
      if(k!==ai && cons.some(c=>c[i]===k&&c[j]===bj)) altA.push(k);
    }
    for(let k=0;k<ST(ds[j]).length;k++){
      if(k!==bj && cons.some(c=>c[i]===ai&&c[j]===k)) altB.push(k);
    }
    out.push({i:i,j:j,ai:ai,bj:bj,altA:altA,altB:altB});
  }
  return {pairs:out, ds:ds, sampled:cimResult.sampled, n:cons.length};
}
function confList(){
  const r=exclPairs();
  if(r.need==='check'){
    el('confList','<div class="dim" style="line-height:1.9;">矛盾是从<b>检验结果</b>里算出来的，先运行一致性检验。'
      +'<div style="margin-top:10px;"><button class="btn sm pri" onclick="runCIM()">运行一致性检验</button></div></div>');
    return;
  }
  if(r.need==='empty'){
    el('confList','<div class="dim">当前没有任何自洽情景，无法判断“哪两个状态不能并存”。先复核打分矩阵，或放宽锚定后重跑检验。</div>');
    return;
  }
  if(r.need==='few'){
    el('confList','<div class="dim">至少选两个描述符才能判断“哪两档不能并存”。</div>');
    return;
  }
  const solo=(r.solo||[]);
  let head='';
  if(solo.length){
    head='<div class="soloBox"><b>孤立档位（'+solo.length+' 个）</b>：'
      +'这些档位在任何自洽情景里都<b>没出现过</b>——不是与哪一档冲突，而是其自身与整体判断不相容。'
      +solo.map(x=>'<br>· '+(DSHORT[r.ds[x.i]]||r.ds[x.i])+'：'+ST(r.ds[x.i])[x.a]).join('')
      +'</div>';
  }
  if(!r.pairs.length){
    el('confList', head+'<div class="dim" style="line-height:1.9;">'
      +'全部档位对都能共存，<b>没有互斥对</b>——这套判断体系里没有相互冲突的要求。</div>');
    return;
  }
  el('confList', head
    + r.pairs.slice(0,40).map((p,idx)=>{
    const dA=r.ds[p.i], dB=r.ds[p.j];
    const sA=ST(dA)[p.ai], sB=ST(dB)[p.bj];
    const open=openConf===idx;
    const altA=p.altA.map(k=>'<button class="btn sm" onclick="applyConfFix(\''+dA+'\','+k+')">'+ST(dA)[k]+'</button>').join(' ');
    const altB=p.altB.map(k=>'<button class="btn sm" onclick="applyConfFix(\''+dB+'\','+k+')">'+ST(dB)[k]+'</button>').join(' ');
    return '<div class="conf">'
      +'<div class="h">互斥 '+(idx+1)+'：'+dA+'（'+sA+'）× '+dB+'（'+sB+'）</div>'
      +'<div>在本次检出的 '+r.nCons+' 组自洽情景里，这两档<b>各自都出现过，却从未同时出现</b>。'
      +(r.sampled?'（结果来自抽样：可能把"未抽到"误判成"不可能"，档位对数量多时请以方向为准。）':'')+'</div>'
      +(open?('<div class="sug"><b>可以这样改（点了会真的改状态并重算）：</b><br>'
        +(altA?('把「'+dA+'」改成：'+altA):('「'+dA+'」没有任何一档能与「'+sB+'」共存，需改另一边或复核打分'))
        +'<br>'
        +(altB?('把「'+dB+'」改成：'+altB):('「'+dB+'」没有任何一档能与「'+sA+'」共存，需改另一边或复核打分'))
        +'</div>'):'')
      +'<div style="margin-top:8px;font-size:13px;">'
      +'<span style="color:var(--pri);cursor:pointer;" onclick="toggleConf('+idx+')">'
      +(open?'收起':'查看可替换的档位 ▼')+'</span></div></div>';
  }).join('')
  +(r.pairs.length>40?('<div class="dim" style="margin-top:9px;">共 '+r.pairs.length+' 对，此处列出最值得看的 40 对。</div>'):''));
}
function toggleConf(i){ openConf=openConf===i?null:i; render(); }
function applyConfFix(nm, idx){
  if(!sel.desc[nm]||idx===undefined||idx===null||idx<0) return;
  /* 采纳建议＝把这一档设成唯一的可信范围。多选语义下必须覆盖而不是追加，
     否则原来勾的两档会一起留下来，用户以为是"改成了"，其实范围反而变宽。 */
  sel.desc[nm].states=[ST(nm)[idx]];
  cimResult=null; BAYES=null; layeredResult=null; corrResult=null; profResult=null;
  openConf=null;
  runCIM();
  toast('已把「'+nm+'」改为「'+ST(nm)[idx]+'」并重新检验');
}
function timeline(){
  const names=Object.keys(sel.desc);
  const rows=names.length?names:['（尚未选择描述符）'];
  el('timeline', `<div class="crow hd" style="grid-template-columns:1fr 1fr 1fr 1fr;">
      <div class="clbl" style="font-weight:400;color:var(--tx3);">描述符</div>
      <div class="cell" style="border-right:1px solid var(--line2);">2025 参照年</div>
      <div class="cell" style="border-right:1px solid var(--line2);">2030 政策锚点</div>
      <div class="cell" style="border-right:none;">2035 情景锚点</div></div>`+
    rows.map(nm=>{
      const d=dOf(nm);
      if(!d) return `<div class="crow" style="grid-template-columns:1fr 1fr 1fr 1fr;">
        <div class="clbl">${nm}</div><div class="cell">—</div><div class="cell">—</div>
        <div class="cell" style="border-right:none;">—</div></div>`;
      return `<div class="crow" style="grid-template-columns:1fr 1fr 1fr 1fr;">
        <div class="clbl">${nm}</div>
        <div class="cell" style="border-right:1px solid var(--line2);">
          <span class="dim">取自统计公报</span></div>
        <div class="cell" style="border-right:1px solid var(--line2);">${d.a30}</div>
        <div class="cell" style="border-right:none;color:var(--tx3);">${d.a35}</div></div>`;
    }).join(''));
}
function el(id,h){ document.getElementById(id).innerHTML=h; }
/* 「标签 ＼ 值」那一行。全项目手拼过 30 多遍，改一次样式要改几十处，故收成一个函数。
   st 是可选的额外内联样式，只给少数需要微调的场合；值里若含 HTML 由调用方自己保证。
   注意：统计条里的 <span class="kv">（.cimstat / .ensstat）是另一种紧凑芯片样式，
   与这里的整行不同，别混用。 */
function kv(l,v,st){
  return '<div class="kv"'+(st?' style="'+st+'"':'')+'><span>'+l+'</span><span>'+v+'</span></div>';
}

/* ================= 导出 ================= */
/* v1.3：参数值不再写「待定」。从状态定义（含省口径）取区间，按取档方式给点值；
   没有区间的状态明确标注"需人工给值"，不假装有数。 */
let expMode='mid';   // low=区间下界（保守） / mid=中点 / high=上界（加码）
function paramOf(d){
  const v=String((d&&d.v)||'').split(/[；;]/)[0].trim();
  return v||'（该描述符未注明模型变量）';
}
function expRows(){
  const names=Object.keys(sel.desc);
  return names.map(nm=>{
    const d=dOf(nm); if(!d) return null;
    const st=(sel.desc[nm].states||[])[0]||'';
    const defs=defsOf(nm), def=defs.filter(x=>x.n===st)[0]||null;
    const lo=(def&&def.lo!=null)?def.lo:null;
    const hi=(def&&def.hi!=null)?def.hi:null;
    const u=(def&&def.u)||'';
    let val=null;
    if(lo!=null||hi!=null){
      const L=(lo!=null?lo:hi), H=(hi!=null?hi:lo);
      val = expMode==='low'?L:(expMode==='high'?H:(L+H)/2);
      val=Math.round(val*1000)/1000;
    }
    return {desc:nm, param:paramOf(d), scope:rngScope||'region', year:2035, state:st,
      value:val, lo:lo, hi:hi, unit:u, ev:(def&&def.ev)||'',
      note: val==null?'该状态未定义数值区间，需人工给值':''};
  }).filter(Boolean);
}
function expLabel(){ return expMode==='low'?'区间下界（保守）':(expMode==='high'?'区间上界（加码）':'区间中点'); }
/* 多选＝划定范围时，单情景导出会按"第一档"取，必须明说——
   这正是 loadCfg 里警告过的「看起来选了三个、实际只用第一个」。 */
function multiPickNote(){
  const names=Object.keys(sel.desc).filter(nm=>selIdxOf(nm).length>1);
  if(!names.length) return '';
  return '注意：'+names.map(nm=>DSHORT[nm]||nm).join('、')+' 勾了多档（＝划定范围），'
    +'下面按每档的<b>第一档</b>取值导出。要按整个范围导出，请用「导出全部自洽情景」；'
    +'要导出某一档，请在该描述符下只勾那一档。';
}
function csvCell(v){
  const t=(v==null?'':String(v));
  return /[",\n]/.test(t)?('"'+t.replace(/"/g,'""')+'"'):t;
}
function preview(){
  const rows=expRows();
  if(curModel==='gcam'){
    let s='<span class="c">&lt;!-- 平台自动生成 · 写入 configuration.xml 的 ScenarioComponents --&gt;</span>\n';
    s+='<span class="c">&lt;!-- 取档方式：'+expLabel()+'；年份锚点 2035；参数值见同目录的参数表 CSV --&gt;</span>\n';
    s+='<span class="c">&lt;!-- '+rows.map(r=>r.desc+' → '+r.param+' = '+(r.value==null?'待人工给值':(r.value+' '+(r.unit||'')))).join('；')+' --&gt;</span>\n';
    const known=[], unknown=[];
    rows.forEach((r,ri)=>{
      const d=dOf(r.desc), f=xmlFile(d,ri);
      (f?known:unknown).push({r:r,d:d,f:f});
    });
    s+='&lt;<span class="k">ScenarioComponents</span>&gt;\n';
    known.slice(0,8).forEach(x=>{
      s+='  &lt;<span class="k">Value</span> <span class="at">name</span>=<span class="s">"'+xmlTag(x.d)+'"</span>&gt;'
        +x.f+'&lt;/<span class="k">Value</span>&gt;\n';
    });
    if(known.length>8) s+='  <span class="c">&lt;!-- 另有 '+(known.length-8)+' 项已确认 --&gt;</span>\n';
    s+='&lt;/<span class="k">ScenarioComponents</span>&gt;';
    if(unknown.length){
      s+='\n<span class="c">&lt;!-- 以下 '+unknown.length+' 个描述符平台无法确定装配文件，需人工补齐：'
        +unknown.map(x=>x.r.desc+'（'+x.r.param+'）').join('；')+' --&gt;</span>';
    }
    return s;
  }
  let s='<span class="c"># 平台自动生成 · CSV，之后由 GDXXRW.EXE 转为 GDX</span>\n';
  s+='<span class="c"># 取档方式：'+expLabel()+'；年份锚点 2035</span>\n';
  s+='param,scenario,value,unit,low,high,state,scope,year,note\n';
  rows.forEach(r=>{
    s+=[csvCell(r.param),csvCell(r.state),r.value==null?'':r.value,csvCell(r.unit),
        r.lo==null?'':r.lo,r.hi==null?'':r.hi,csvCell(r.state),r.scope,r.year,csvCell(r.note)].join(',')+'\n';
  });
  return s;
}
function paramsCSV(){
  const rows=expRows();
  let s='# 参数表 · 平台自动生成\n';
  s+='# 取档方式：'+expLabel()+'；值只覆盖 2035 锚点，2025/2030 需按政策里程碑插值\n';
  s+='descriptor,param,scope,year,value,low,high,unit,state,evidence,note\n';
  rows.forEach(r=>{
    s+=[csvCell(r.desc),csvCell(r.param),csvCell(r.scope),r.year,
        r.value==null?'':r.value,r.lo==null?'':r.lo,r.hi==null?'':r.hi,csvCell(r.unit),
        csvCell(r.state),csvCell(r.ev),csvCell(r.note)].join(',')+'\n';
  });
  const mp=Object.keys(sel.desc).filter(nm=>selIdxOf(nm).length>1);
  if(mp.length){
    s+='# 注意：'+mp.map(nm=>nm).join('、')+' 勾了多档（＝划定范围），本表按每档的第一档取值。\n';
    s+='# 要按整个范围导出，请用「导出全部自洽情景」。\n';
  }
  return s;
}
function downloadParams(){ dl(paramsCSV(),'csv','JJJ-CIB-参数表'); }
function setExpMode(v){ expMode=v; render(); }

/* --- 四种参数生成形态：同一套状态与区间，导成四种东西 --- */
function narrText(){
  const rows=expRows();
  if(!rows.length) return '（还没有选描述符）';
  const sc=Object.keys(sel.desc).map(nm=>(sel.desc[nm].states||[])[0]).filter(Boolean);
  const note=multiPickNote();
  let s='【情景特征】\n本情景在'+nSel()+'个描述符上取了'+sc.length+'档，构成一组自洽的政策情景假设。\n\n';
  if(note) s+='【注意】'+note.replace(/<[^>]+>/g,'')+'\n\n';
  s+='【逐项特征】\n';
  rows.forEach(r=>{
    s+='· '+r.desc+'：取「'+r.state+'」档';
    if(r.value==null) s+='（该档未设数值区间，需人工给档）';
    else{
      s+='，对应 '+r.value+(r.unit||'');
      if(r.lo!=null&&r.hi!=null) s+='（区间 '+r.lo+' – '+r.hi+(r.unit||'')+'）';
    }
    s+='。\n';
  });
  s+='\n【说明】\n以上为定性描述，不含模型可读的数值参数；要落到下游模型请改用「模型配置文件」或「结构化参数表」。';
  return s;
}
function bayesCSV(){
  if(!BAYES) computeBayes();
  const keys=BAYES?Object.keys(BAYES.cells):[];
  let s='# 贝叶斯后验 · 每条判断的后验分布\n';
  s+='# 先验 N(0, '+2.2+'²)，按置信度给噪声（高 .55 / 中 .85 / 低 1.25），网格积分得后验\n';
  s+='pair,observations,posterior_mean,sd,p05,p95,width,p_promote,p_suppress,p_flat\n';
  keys.forEach(k=>{
    const c=BAYES.cells[k];
    s+=[csvCell(k),c.n,c.mean.toFixed(3),c.sd.toFixed(3),c.lo.toFixed(3),c.hi.toFixed(3),
        (c.hi-c.lo).toFixed(3),c.pPos.toFixed(3),c.pNeg.toFixed(3),c.pFlat.toFixed(3)].join(',')+'\n';
  });
  return s;
}
/* 结构化参数表：只留参数名与数值，去掉依据、叙述、状态名等给人看的列。
   但 CIB 求出的是一组「联动自洽」的组合——同一个描述符取哪一档，取决于其他描述符取什么。
   把参数拆成一行行独立数值，等于把耦合又拆散，下游按行取用会得到互相矛盾的一组值。
   所以每行都带上它所属的情景标识，并在表头写明「同一 scenario 内才自洽、跨 scenario 混用会破坏一致性」。 */
function curScenInfo(){
  const ds=Object.keys(sel.desc);
  if(ds.length<2) return null;
  const sc=checkSelected(ds);
  if(sc.missing) return null;
  let idx=-1;
  if(cimResult&&cimResult.consistent){
    const key=sc.cb.join(',');
    idx=cimResult.consistent.findIndex(cb=>cb.join(',')===key);
  }
  return {id:'CUR'+(idx>=0?('-S'+(idx+1)):''), idx:idx, ok:sc.ok, n:ds.length};
}
function tableCSV(){
  const rows=expRows();
  const info=curScenInfo();
  let s='# 结构化参数表 · 平台自动生成\n';
  s+='# 取档方式：'+expLabel()+'；值只覆盖 2035 锚点\n';
  s+='# 同一 scenario 内的参数构成一组自洽组合；跨 scenario 混用会破坏一致性。\n';
  if(info){
    s+='# 本表全部行同属 '+info.id+'（'+info.n+' 个描述符的当前选择）';
    s+=info.idx>=0?('，已与一致性检验的第 '+(info.idx+1)+' 组自洽情景对上'):'，未出现在自洽情景清单中';
    s+='。\n';
    if(!info.ok){
      s+='# 注意：这组选择本身不自洽——至少有一个描述符的选定状态不是它的最高分。\n';
      s+='# 取用前请回到平台「检验与导出」核对，或改用清单里的某一组自洽情景。\n';
    }
  }else{
    s+='# 尚未选出足够的描述符，无法判定这组参数是否自洽。\n';
  }
  s+='scenario,param,value\n';
  rows.forEach(r=>{
    if(r.value==null) return;                  // 没数值的不进参数表，另行列出
    s+=[(info?info.id:'CUR'),csvCell(r.param),r.value].join(',')+'\n';
  });
  return s;
}
