    +'<button class="btn" onclick="exportFramework()">导出框架 JSON</button>'
    +'<label class="btn" style="display:inline-flex;align-items:center;">导入框架 JSON'
      +'<input type="file" accept=".json,application/json" style="display:none" onchange="importFramework(this)"></label>'
